SELECT 'seed 8 U1 inner UNION' AS q;
(SELECT t2a.c3 AS k0, t2a.c3 AS k1, t2a.c1 AS k2 FROM t2 AS t2a) UNION (SELECT t1b.c4 AS k0, t1c.c4 AS k1, t1c.c1 AS k2 FROM t2 AS t2a INNER JOIN t1 AS t1b ON NOT ((0)) INNER JOIN t1 AS t1c ON NOT ((0)));
SELECT 'seed 8 U2 A UNION (inner UNION)' AS q;
(SELECT t2a.c3 AS k0, t2a.c15 AS k1, t2a.c3 AS k2 FROM t2 AS t2a) UNION ((SELECT t2a.c3 AS k0, t2a.c3 AS k1, t2a.c1 AS k2 FROM t2 AS t2a) UNION (SELECT t1b.c4 AS k0, t1c.c4 AS k1, t1c.c1 AS k2 FROM t2 AS t2a INNER JOIN t1 AS t1b ON NOT ((0)) INNER JOIN t1 AS t1c ON NOT ((0))));
SELECT 'seed 8 U3 A UNION (inner UNION ALL): the same rows as U2' AS q;
(SELECT t2a.c3 AS k0, t2a.c15 AS k1, t2a.c3 AS k2 FROM t2 AS t2a) UNION ((SELECT t2a.c3 AS k0, t2a.c3 AS k1, t2a.c1 AS k2 FROM t2 AS t2a) UNION ALL (SELECT t1b.c4 AS k0, t1c.c4 AS k1, t1c.c1 AS k2 FROM t2 AS t2a INNER JOIN t1 AS t1b ON NOT ((0)) INNER JOIN t1 AS t1c ON NOT ((0))));
SELECT 'seed 8 U4 A UNION ALL (inner UNION): U2 is its set' AS q;
(SELECT t2a.c3 AS k0, t2a.c15 AS k1, t2a.c3 AS k2 FROM t2 AS t2a) UNION ALL ((SELECT t2a.c3 AS k0, t2a.c3 AS k1, t2a.c1 AS k2 FROM t2 AS t2a) UNION (SELECT t1b.c4 AS k0, t1c.c4 AS k1, t1c.c1 AS k2 FROM t2 AS t2a INNER JOIN t1 AS t1b ON NOT ((0)) INNER JOIN t1 AS t1c ON NOT ((0))));
