SELECT DISTINCT AVG(t1a.c1) AS k0, STDDEV_SAMP((t1a.c1 - 1)) AS k1, (COUNT(t1a.c1) + 1) AS k2 FROM t1 AS t1a;
SELECT 'seed 140 V3 without DISTINCT, without COUNT' AS q;
SELECT AVG(t1a.c1) AS k0, STDDEV_SAMP((t1a.c1 - 1)) AS k1 FROM t1 AS t1a;
SELECT 'seed 140 V4 the column' AS q;
SELECT t1a.c1 FROM t1 AS t1a ORDER BY 1;
